        return { openThreadsAtMerge: 0, autoResolved: 0, machine: 0, human: 0 };
    }
    var counted = Array.isArray(bs.counted) ? bs.counted.length : 0;
    var ack = Array.isArray(bs.ackThreads) ? bs.ackThreads.length : 0;
