    var human = Array.isArray(bs.human) ? bs.human.length : 0;
    return {
        openThreadsAtMerge: counted + ack + hold + human,
        autoResolved: (bs.resolved || 0) + (bs.ackResolved || 0),
        machine: counted + ack + hold,
        human: human
    };
