    releaseLock(ctx);
    closeIssueSafetyNet(ctx.issueNumber);
    return true;
}

function squashAndFinalize(ctx, pr) {
    // gh-1416: the held path releases the lock and returns false — the SM
    // retries next cycle, the rework lap / a human resolution lands the
