    var gate = mergeGateOutcomeForPr(ctx.jobParams, ctx.owner, ctx.repo, pr.number, pr.detail);
    if (gate.held) return gateHoldExit(ctx, pr, prPayload, gate, verdictGate);
    // Merge (squash — merge-trigger parity).
